+        Op == ISD::ANY_EXTEND) {
+      V = V.getOperand(0);
+      assert(V.getScalarValueSizeInBits() >= Log2_32(BW) &&
+             "low bits constraint must survive width adjustment");
+      LowBits = LowBits.zextOrTrunc(V.getScalarValueSizeInBits());
+      continue;
